L['fr-verbgruppe-02-pronomenstellung']=SKContent.pool("app-27-33480",{"hook":"","intro":{"lead":"","core":"","why":""},"objectives":[],"blocks":[],"examples":[],"points":[],"mistake":"","mnemonic":"","summary":"","essentials":[]});

L["v76-smp-french-01-leseverstehen"].essentials=["Vor dir liegen ein französischer Text und Fragen dazu; du kennst nicht jedes Wort.", "Du liest zuerst im Überblick (Titel, Anfang und Schluss, erste Sätze der Absätze) und suchst dann für jede Frage die genaue Stelle.", "So findest du die Antwort an einer bestimmten Stelle im Text und kannst sie mit der Zeile belegen.", "Deine Antwort nennt die Zeile und stimmt auch bei Verneinungen und Gegensätzen genau mit dem Text überein."];
L["v76-smp-french-03-schriftlicher-ausdruck"].essentials=["Du hast eine Schreibaufgabe mit Textsorte, Empfänger und mehreren Inhaltspunkten.", "Du bestimmst den Ton (tu oder vous), planst Einleitung, Hauptteil und Schluss und verbindest die Absätze mit Konnektoren.", "So entsteht ein klar aufgebauter Text, der jeden verlangten Punkt in einem eigenen Absatz behandelt.", "Alle Inhaltspunkte sind behandelt, tu und vous sind nicht gemischt, und die Sprach-Checkliste ist abgearbeitet."];
L["v76-smp-french-02-morphosyntax-und-wortschatz"].essentials=["Du sollst in einem französischen Satz eine Form wählen: Zeitform, Modus oder Pronomen.", "Du stellst die passende Leitfrage: Hintergrund oder Ereignis? Tatsache oder Wunsch, Gefühl, Zweifel? Mit oder ohne à?", "Die Antwort auf die Leitfrage bestimmt die Form: imparfait oder passé composé, indicatif oder subjonctif, le oder lui.", "Der Satz ist richtig, wenn die Form zur Aussageabsicht passt und Angleichung und Stellung stimmen."];
